import React, { Suspense, useMemo, useRef, useState, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import {
  OrbitControls,
  useGLTF,
  Environment,
  Grid,
  PerspectiveCamera,
  ContactShadows,
  GizmoHelper,
  GizmoViewport,
  Html,
} from '@react-three/drei';
import * as THREE from 'three';
import {
  Download,
  RotateCw,
  Box,
  Eye,
  Sparkles,
  Layers,
  RefreshCw,
  AlertCircle,
  ExternalLink,
} from 'lucide-react';

/**
 * Inner component to load and auto-normalize the GLB mesh generated by Tripo AI.
 */
function GlbModelMesh({ url, showWireframe, autoRotate, onStatsReady }) {
  const { scene } = useGLTF(url);
  const modelRef = useRef();

  // Clone scene and auto-center / scale
  const { clonedScene, boundingInfo } = useMemo(() => {
    const cloned = scene.clone(true);

    // Compute bounding box
    const box = new THREE.Box3().setFromObject(cloned);
    const size = new THREE.Vector3();
    const center = new THREE.Vector3();
    box.getSize(size);
    box.getCenter(center);

    // Normalize scale so largest dimension is ~24 units in scene
    const maxDim = Math.max(size.x, size.y, size.z);
    const targetDim = 24.0;
    const scale = maxDim > 0 ? targetDim / maxDim : 1.0;

    cloned.scale.set(scale, scale, scale);

    // Recalculate after scale
    const scaledBox = new THREE.Box3().setFromObject(cloned);
    const scaledCenter = new THREE.Vector3();
    scaledBox.getCenter(scaledCenter);

    // Center X & Z at 0, place lowest point at Y = 0
    cloned.position.x = -scaledCenter.x;
    cloned.position.z = -scaledCenter.z;
    cloned.position.y = -scaledBox.min.y;

    // Traverse and apply materials / shadows
    let vertexCount = 0;
    let meshCount = 0;

    cloned.traverse((child) => {
      if (child.isMesh) {
        meshCount++;
        child.castShadow = true;
        child.receiveShadow = true;

        if (child.geometry?.attributes?.position) {
          vertexCount += child.geometry.attributes.position.count;
        }

        if (child.material) {
          child.material.wireframe = showWireframe;
          child.material.roughness = Math.min(0.9, child.material.roughness || 0.6);
          child.material.metalness = Math.max(0.1, child.material.metalness || 0.2);
          child.material.needsUpdate = true;
        }
      }
    });

    return {
      clonedScene: cloned,
      boundingInfo: {
        widthM: Math.round(size.x * 10) / 10,
        heightM: Math.round(size.y * 10) / 10,
        lengthM: Math.round(size.z * 10) / 10,
        vertexCount,
        meshCount,
      },
    };
  }, [scene, showWireframe]);

  useEffect(() => {
    onStatsReady?.(boundingInfo);
  }, [boundingInfo, onStatsReady]);

  return <primitive ref={modelRef} object={clonedScene} />;
}

/**
 * High-fidelity 3D Canvas viewer for Tripo AI generated GLB rooftop models.
 */
export const TripoModelViewer = ({
  modelUrl,
  taskId,
  imageUrl,
  onReset,
}) => {
  const [showWireframe, setShowWireframe] = useState(false);
  const [autoRotate, setAutoRotate] = useState(false);
  const [showGrid, setShowGrid] = useState(true);
  const [modelStats, setModelStats] = useState(null);

  return (
    <div className="relative w-full h-full flex flex-col min-h-[620px] bg-slate-950 rounded-2xl overflow-hidden border border-slate-800">
      {/* Top Floating Control Bar */}
      <div className="absolute top-3 left-3 right-3 z-10 flex items-center justify-between pointer-events-none">
        {/* Model Meta Badge */}
        <div className="pointer-events-auto flex items-center gap-2.5 bg-slate-900/90 backdrop-blur-md px-3.5 py-1.5 rounded-xl border border-blue-500/30 text-white shadow-lg">
          <Sparkles size={14} className="text-blue-400 animate-pulse" />
          <span className="text-xs font-bold tracking-wide">Tripo AI V3 3D Mesh</span>
          {modelStats && (
            <span className="text-[10px] bg-blue-500/20 text-blue-300 font-mono px-2 py-0.5 rounded">
              {modelStats.vertexCount?.toLocaleString()} Vertices
            </span>
          )}
        </div>

        {/* Action Buttons */}
        <div className="pointer-events-auto flex items-center gap-2">
          <button
            type="button"
            onClick={() => setShowWireframe((w) => !w)}
            className={`p-2 rounded-xl text-xs font-medium border transition-colors cursor-pointer flex items-center gap-1.5 ${
              showWireframe
                ? 'bg-blue-600 text-white border-blue-500'
                : 'bg-slate-900/80 text-slate-300 border-slate-700 hover:bg-slate-800'
            }`}
            title="Toggle Wireframe"
          >
            <Layers size={14} />
            <span className="hidden sm:inline">Wireframe</span>
          </button>

          <button
            type="button"
            onClick={() => setAutoRotate((r) => !r)}
            className={`p-2 rounded-xl text-xs font-medium border transition-colors cursor-pointer flex items-center gap-1.5 ${
              autoRotate
                ? 'bg-blue-600 text-white border-blue-500'
                : 'bg-slate-900/80 text-slate-300 border-slate-700 hover:bg-slate-800'
            }`}
            title="Auto Rotate"
          >
            <RotateCw size={14} className={autoRotate ? 'animate-spin' : ''} />
            <span className="hidden sm:inline">Turntable</span>
          </button>

          <a
            href={modelUrl}
            download={`solarscope_rooftop_${taskId || 'tripo'}.glb`}
            target="_blank"
            rel="noopener noreferrer"
            className="p-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-xl transition-all shadow-md flex items-center gap-1.5 cursor-pointer"
            title="Download .GLB Model"
          >
            <Download size={14} />
            <span>Download .GLB</span>
          </a>

          {onReset && (
            <button
              type="button"
              onClick={onReset}
              className="p-2 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold rounded-xl border border-slate-700 transition-colors cursor-pointer"
              title="Generate New Model"
            >
              <RefreshCw size={14} />
            </button>
          )}
        </div>
      </div>

      {/* 3D WebGL Canvas */}
      <div className="w-full h-full flex-1 min-h-[580px]">
        <Canvas
          shadows
          dpr={[1, 2]}
          className="w-full h-full"
          style={{
            background: 'radial-gradient(circle at 50% 30%, #1e293b 0%, #070a12 100%)',
          }}
          onCreated={({ gl }) => {
            gl.shadowMap.enabled = true;
            gl.shadowMap.type = THREE.PCFSoftShadowMap;
            gl.toneMapping = THREE.ACESFilmicToneMapping;
            gl.toneMappingExposure = 1.2;
          }}
        >
          <PerspectiveCamera makeDefault position={[22, 16, 22]} fov={45} near={0.1} far={1000} />
          <OrbitControls
            enableDamping
            dampingFactor={0.06}
            autoRotate={autoRotate}
            autoRotateSpeed={1.8}
            maxPolarAngle={Math.PI / 2 - 0.02}
            minDistance={4}
            maxDistance={250}
          />

          {/* Lighting Rig */}
          <ambientLight intensity={0.7} color="#f0f6fc" />
          <directionalLight
            position={[40, 60, 30]}
            intensity={2.8}
            color="#fff8e7"
            castShadow
            shadow-mapSize-width={2048}
            shadow-mapSize-height={2048}
            shadow-bias={-0.0003}
          />
          <directionalLight position={[-30, 25, -20]} intensity={0.5} color="#94a3b8" />
          <hemisphereLight skyColor="#dbeafe" groundColor="#334155" intensity={0.5} />

          {/* Ground Soft Contact Shadow */}
          <ContactShadows
            position={[0, 0, 0]}
            opacity={0.7}
            scale={60}
            blur={1.6}
            far={30}
            resolution={1024}
            color="#090d16"
          />

          {/* Metric Floor Grid */}
          {showGrid && (
            <Grid
              args={[120, 120]}
              position={[0, -0.01, 0]}
              cellSize={1}
              cellThickness={0.4}
              cellColor="#64748b"
              sectionSize={5}
              sectionThickness={1.0}
              sectionColor="#475569"
              fadeDistance={60}
              fadeStrength={1.2}
              infiniteGrid
            />
          )}

          {/* Tripo Generated GLB Model */}
          <Suspense
            fallback={
              <Html center>
                <div className="flex flex-col items-center gap-2 bg-slate-900/90 text-white px-4 py-3 rounded-xl border border-blue-500/40 backdrop-blur-md shadow-2xl">
                  <RefreshCw size={20} className="animate-spin text-blue-400" />
                  <span className="text-xs font-semibold">Streaming 3D GLB mesh...</span>
                </div>
              </Html>
            }
          >
            <GlbModelMesh
              url={modelUrl}
              showWireframe={showWireframe}
              autoRotate={autoRotate}
              onStatsReady={setModelStats}
            />
            <Environment preset="city" />
          </Suspense>

          {/* Compass Gizmo */}
          <GizmoHelper alignment="bottom-right" margin={[70, 70]}>
            <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
          </GizmoHelper>
        </Canvas>
      </div>

      {/* Bottom Model Details Bar */}
      <div className="absolute bottom-3 left-3 z-10 flex items-center gap-3 bg-slate-950/85 backdrop-blur-md px-3.5 py-2 rounded-xl border border-slate-800 text-xs text-slate-300">
        <span className="font-semibold text-blue-400">Rooftop 3D Digital Asset</span>
        {taskId && (
          <span className="font-mono text-[10px] text-slate-500 border-l border-slate-800 pl-3">
            Task: {taskId.slice(0, 12)}...
          </span>
        )}
        {imageUrl && (
          <a
            href={imageUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="text-[11px] text-slate-400 hover:text-white flex items-center gap-1 border-l border-slate-800 pl-3 transition-colors"
          >
            <span>Input Image</span>
            <ExternalLink size={10} />
          </a>
        )}
      </div>
    </div>
  );
};
